input.function:
() => {
  const pick = (sel) => { const el = document.querySelector(sel); if(!el) return null; const s=getComputedStyle(el); const r=el.getBoundingClientRect(); return {bg:s.backgroundColor,color:s.color,border:s.borderColor,bw:s.borderWidth,fs:s.fontSize,fw:s.fontWeight,pad:s.padding,w:Math.round(r.width),h:Math.round(r.height),left:Math.round(r.left),top:Math.round(r.top)}; };
  const out = {};
  out.wrapper = pick('.wrapper');
  out.leftBar = pick('.left-bar') || pick('[class*=left]');
  out.tools = pick('.tools');
  out.toolItem = pick('.tools .item') || pick('.tools > *');
  out.rightPanel = pick('.right-panel') || pick('[class*=right]');
  out.block = pick('.block');
  out.blockHeader = pick('.block .header, .header');
  out.mainMenu = pick('nav ul') || pick('nav');
  out.canvasArea = pick('#canvas_area, .canvas_area');
  out.canvas = pick('canvas');
  return out;
}

() => {
  const r = (sel) => { const el=document.querySelector(sel); if(!el) return null; const b=el.getBoundingClientRect(); return {x:Math.round(b.x),y:Math.round(b.y),w:Math.round(b.width),h:Math.round(b.height)}; };
  const out={};
  out.leftBar = r('.left-bar');
  out.rightPanel = r('[class*=right]');
  out.canvasArea = r('[class*=canvas_area]');
  out.topArea = r('[class*=top]');
  // enumerate left-bar tool items
  const lb = document.querySelector('.left-bar');
  if(lb) out.leftBarHTMLsample = [...lb.children].map(c=>({tag:c.tagName, cls:c.className, title:c.getAttribute('title')||c.getAttribute('data-tool')||''}));
  return out;
}

