() => {
  const el = (sel) => document.querySelector(sel);
  const s = (sel, props) => { const e=el(sel); if(!e) return null; const c=getComputedStyle(e); const o={}; props.forEach(p=>o[p]=c[p]); return o; };
  const out={};
  out.blockHeader = s('.block .header', ['backgroundColor','color','padding','fontSize','fontWeight','height','borderBottom']);
  out.blockBody = s('.colors.block .content', ['backgroundColor','padding']);
  out.canvasAreaBg = s('.canvas_area', ['backgroundColor']);
  out.bodyBg = getComputedStyle(document.body).backgroundColor;
  out.toolItem = s('.sidebar_left .item', ['backgroundColor','backgroundImage']);
  out.toolActive = s('.sidebar_left .item.active', ['backgroundColor','backgroundImage']);
  out.block = s('.block', ['backgroundColor','borderRadius','margin']);
  out.previewWrap = s('.canvas_preview_wrapper', ['backgroundColor','border']);
  out.layerRow = s('.layers .item, #layers .item', ['backgroundColor','color','padding']);
  out.input = s('input[type=text], input:not([type])', ['backgroundColor','color','border','fontSize']);
  return out;
}

