import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { DialogState, FieldDef, Layer, Point, Rect, ToolId } from "./types";
import { RESOLUTIONS } from "./data";

interface LayerRuntime extends Omit<Layer, "data"> {
  canvas: HTMLCanvasElement;
}

interface Snapshot {
  layers: { id: number; name: string; visible: boolean; opacity: number; x: number; y: number; pixels: ImageData }[];
  activeId: number;
  width: number;
  height: number;
}

let layerSeq = 1;

function makeCanvas(w: number, h: number): HTMLCanvasElement {
  const c = document.createElement("canvas");
  c.width = Math.max(1, Math.round(w));
  c.height = Math.max(1, Math.round(h));
  return c;
}

function hexToRgb(hex: string) {
  const m = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex.trim());
  if (!m) return { r: 0, g: 0, b: 0 };
  return { r: parseInt(m[1], 16), g: parseInt(m[2], 16), b: parseInt(m[3], 16) };
}

function rgbToHex(r: number, g: number, b: number) {
  const t = (n: number) => Math.max(0, Math.min(255, Math.round(n))).toString(16).padStart(2, "0");
  return `#${t(r)}${t(g)}${t(b)}`;
}

/** HSV (h 0..360, s/v 0..1) -> rgb */
function hsvToRgb(h: number, s: number, v: number) {
  const c = v * s;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = v - c;
  let r = 0,
    g = 0,
    b = 0;
  if (h < 60) [r, g, b] = [c, x, 0];
  else if (h < 120) [r, g, b] = [x, c, 0];
  else if (h < 180) [r, g, b] = [0, c, x];
  else if (h < 240) [r, g, b] = [0, x, c];
  else if (h < 300) [r, g, b] = [x, 0, c];
  else [r, g, b] = [c, 0, x];
  return { r: (r + m) * 255, g: (g + m) * 255, b: (b + m) * 255 };
}

function rgbToHsv(r: number, g: number, b: number) {
  r /= 255;
  g /= 255;
  b /= 255;
  const max = Math.max(r, g, b),
    min = Math.min(r, g, b);
  const d = max - min;
  let h = 0;
  if (d !== 0) {
    if (max === r) h = ((g - b) / d) % 6;
    else if (max === g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
    h *= 60;
    if (h < 0) h += 360;
  }
  const s = max === 0 ? 0 : d / max;
  return { h, s, v: max };
}

export function useEditor() {
  const [width, setWidth] = useState(462);
  const [height, setHeight] = useState(346);
  const [layerMeta, setLayerMeta] = useState<Layer[]>([]);
  const [activeLayerId, setActiveLayerId] = useState(1);
  const [tool, setTool] = useState<ToolId>("brush");
  const [shapeTool, setShapeTool] = useState("rectangle");
  const [color, setColor] = useState("#008000");
  const [brushSize, setBrushSize] = useState(4);
  const [pressure, setPressure] = useState(false);
  const [zoom, setZoom] = useState(100);
  const [mouse, setMouse] = useState<Point | null>(null);
  const [grid, setGrid] = useState(false);
  const [ruler, setRuler] = useState(false);
  const [guides, setGuides] = useState<{ id: number; type: "vertical" | "horizontal"; position: number }[]>([]);
  const [fullscreen, setFullscreen] = useState(false);
  const [resolution, setResolution] = useState("72");
  const [dialog, setDialog] = useState<DialogState | null>(null);
  const [status, setStatus] = useState("");
  const [selection, setSelection] = useState<Rect | null>(null);
  const [, forceRender] = useState(0);

  const reRender = useCallback(() => forceRender((n) => n + 1), []);

  const layerRefs = useRef<Map<number, LayerRuntime>>(new Map());
  const displayRef = useRef<HTMLCanvasElement | null>(null);
  const history = useRef<Snapshot[]>([]);
  const future = useRef<Snapshot[]>([]);
  const clipRef = useRef<HTMLCanvasElement | null>(null);

  /* ---- layer creation ---- */
  const initLayers = useCallback((w: number, h: number, fill = "#ffffff") => {
    layerRefs.current.clear();
    const id = layerSeq++;
    const rt: LayerRuntime = { id, name: "Brush #1", visible: true, opacity: 100, x: 0, y: 0, canvas: makeCanvas(w, h) };
    const ctx = rt.canvas.getContext("2d")!;
    ctx.fillStyle = fill;
    ctx.fillRect(0, 0, w, h);
    layerRefs.current.set(id, rt);
    setActiveLayerId(id);
    return id;
  }, []);

  useEffect(() => {
    initLayers(462, 346);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const W = width;
  const H = height;

  /* ---- composite ---- */
  const composite = useCallback(() => {
    const disp = displayRef.current;
    if (!disp) return;
    const ctx = disp.getContext("2d")!;
    ctx.clearRect(0, 0, disp.width, disp.height);
    for (const [, rt] of layerRefs.current) {
      if (!rt.visible) continue;
      ctx.globalAlpha = Math.max(0, Math.min(1, rt.opacity / 100));
      ctx.drawImage(rt.canvas, rt.x, rt.y);
    }
    ctx.globalAlpha = 1;
  }, []);

  /* ---- snapshots / history ---- */
  const snapshot = useCallback((): Snapshot => {
    const layers = [...layerRefs.current.values()].map((rt) => ({
      id: rt.id,
      name: rt.name,
      visible: rt.visible,
      opacity: rt.opacity,
      x: rt.x,
      y: rt.y,
      pixels: (() => {
        const c = rt.canvas.getContext("2d")!;
        return c.getImageData(0, 0, rt.canvas.width, rt.canvas.height);
      })(),
    }));
    return { layers, activeId: activeLayerId, width: W, height: H };
  }, [activeLayerId, W, H]);

  const pushHistory = useCallback(() => {
    history.current.push(snapshot());
    if (history.current.length > 40) history.current.shift();
    future.current = [];
  }, [snapshot]);

  const restore = useCallback((s: Snapshot) => {
    layerRefs.current.clear();
    for (const l of s.layers) {
      const c = makeCanvas(s.width, s.height);
      c.getContext("2d")!.putImageData(l.pixels, 0, 0);
      layerRefs.current.set(l.id, {
        id: l.id,
        name: l.name,
        visible: l.visible,
        opacity: l.opacity,
        x: l.x,
        y: l.y,
        canvas: c,
      });
    }
    setWidth(s.width);
    setHeight(s.height);
    setActiveLayerId(s.activeId);
    reRender();
    requestAnimationFrame(() => composite());
  }, [composite, reRender]);

  const undo = useCallback(() => {
    const prev = history.current.pop();
    if (!prev) return setStatus("Nothing to undo");
    future.current.push(snapshot());
    restore(prev);
    setStatus("Undo");
  }, [restore, snapshot]);

  const redo = useCallback(() => {
    const next = future.current.pop();
    if (!next) return setStatus("Nothing to redo");
    history.current.push(snapshot());
    restore(next);
    setStatus("Redo");
  }, [restore, snapshot]);

  /* keep meta list in sync with runtime map */
  const syncMeta = useCallback(() => {
    setLayerMeta(
      [...layerRefs.current.values()].map((rt) => ({
        id: rt.id,
        name: rt.name,
        visible: rt.visible,
        opacity: rt.opacity,
        x: rt.x,
        y: rt.y,
        data: "",
      }))
    );
    reRender();
    composite();
  }, [composite, reRender]);

  useEffect(() => {
    syncMeta();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const active = useCallback((): LayerRuntime | null => {
    return layerRefs.current.get(activeLayerId) ?? [...layerRefs.current.values()].pop() ?? null;
  }, [activeLayerId]);

  /* ---- coordinate mapping ---- */
  const toImageCoords = useCallback(
    (clientX: number, clientY: number): Point | null => {
      const disp = displayRef.current;
      if (!disp) return null;
      const r = disp.getBoundingClientRect();
      const scaleX = disp.width / r.width;
      const scaleY = disp.height / r.height;
      return { x: (clientX - r.left) * scaleX, y: (clientY - r.top) * scaleY };
    },
    []
  );

  /* ---- effects on pixel data ---- */
  const applyToActive = useCallback(
    (fn: (d: ImageData) => void, label: string) => {
      const rt = active();
      if (!rt) return;
      pushHistory();
      const ctx = rt.canvas.getContext("2d")!;
      const img = ctx.getImageData(0, 0, rt.canvas.width, rt.canvas.height);
      fn(img);
      ctx.putImageData(img, 0, 0);
      setStatus(label);
      syncMeta();
    },
    [active, pushHistory, syncMeta]
  );

  const eachPixel = (d: ImageData, fn: (r: number, g: number, b: number, a: number) => [number, number, number, number]) => {
    const p = d.data;
    for (let i = 0; i < p.length; i += 4) {
      const [r, g, b, a] = fn(p[i], p[i + 1], p[i + 2], p[i + 3]);
      p[i] = r;
      p[i + 1] = g;
      p[i + 2] = b;
      p[i + 3] = a;
    }
  };

  const effects: Record<string, (label: string) => void> = useMemo(
    () => ({
      grayscale: (l) => applyToActive((d) => eachPixel(d, (r, g, b, a) => { const v = 0.299 * r + 0.587 * g + 0.114 * b; return [v, v, v, a]; }), l),
      invert: (l) => applyToActive((d) => eachPixel(d, (r, g, b, a) => [255 - r, 255 - g, 255 - b, a]), l),
      sepia: (l) =>
        applyToActive(
          (d) =>
            eachPixel(d, (r, g, b, a) => [
              Math.min(255, 0.393 * r + 0.769 * g + 0.189 * b),
              Math.min(255, 0.349 * r + 0.686 * g + 0.168 * b),
              Math.min(255, 0.272 * r + 0.534 * g + 0.131 * b),
              a,
            ]),
          l
        ),
      brightness: (l) => applyToActive((d) => eachPixel(d, (r, g, b, a) => [r + 20, g + 20, b + 20, a]), l),
      contrast: (l) =>
        applyToActive((d) => eachPixel(d, (r, g, b, a) => { const f = 1.3; return [f * (r - 128) + 128, f * (g - 128) + 128, f * (b - 128) + 128, a]; }), l),
      saturation: (l) =>
        applyToActive((d) => eachPixel(d, (r, g, b, a) => { const v = 0.299 * r + 0.587 * g + 0.114 * b; const f = 1.4; return [v + f * (r - v), v + f * (g - v), v + f * (b - v), a]; }), l),
      noise: (l) =>
        applyToActive((d) => eachPixel(d, (r, g, b, a) => { const n = (Math.random() - 0.5) * 60; return [r + n, g + n, b + n, a]; }), l),
      pixelate: (l) =>
        applyToActive((d) => {
          const s = 8;
          const { width: w, height: h, data: p } = d;
          for (let y = 0; y < h; y += s)
            for (let x = 0; x < w; x += s) {
              let r = 0, g = 0, b = 0, a = 0, n = 0;
              for (let yy = y; yy < Math.min(y + s, h); yy++)
                for (let xx = x; xx < Math.min(x + s, w); xx++) {
                  const i = (yy * w + xx) * 4;
                  r += p[i]; g += p[i + 1]; b += p[i + 2]; a += p[i + 3]; n++;
                }
              r /= n; g /= n; b /= n; a /= n;
              for (let yy = y; yy < Math.min(y + s, h); yy++)
                for (let xx = x; xx < Math.min(x + s, w); xx++) {
                  const i = (yy * w + xx) * 4;
                  p[i] = r; p[i + 1] = g; p[i + 2] = b; p[i + 3] = a;
                }
            }
        }, l),
      emboss: (l) =>
        applyToActive((d) => {
          const { width: w, height: h, data: p } = d;
          const copy = new Uint8ClampedArray(p);
          const k = [-2, -1, 0, -1, 1, 1, 0, 1, 2];
          for (let y = 1; y < h - 1; y++)
            for (let x = 1; x < w - 1; x++) {
              let r = 0, g = 0, b = 0;
              let n = 0;
              for (let dy = -1; dy <= 1; dy++)
                for (let dx = -1; dx <= 1; dx++) {
                  const i = ((y + dy) * w + (x + dx)) * 4;
                  const kk = k[n++];
                  r += copy[i] * kk; g += copy[i + 1] * kk; b += copy[i + 2] * kk;
                }
              const i = (y * w + x) * 4;
              p[i] = r + 128; p[i + 1] = g + 128; p[i + 2] = b + 128;
            }
        }, l),
      blueprint: (l) =>
        applyToActive((d) => eachPixel(d, (r, g, b, a) => { const v = 0.299 * r + 0.587 * g + 0.114 * b; return [v * 0.2, v * 0.4, 255 - v * 0.2, a]; }), l),
      nightvision: (l) =>
        applyToActive((d) => eachPixel(d, (r, g, b, a) => { const v = 0.299 * r + 0.587 * g + 0.114 * b; return [v * 0.1, Math.min(255, v * 1.4) , v * 0.1, a]; }), l),
      heatmap: (l) =>
        applyToActive((d) => eachPixel(d, (r, g, b, a) => { const v = (0.299 * r + 0.587 * g + 0.114 * b) / 255; return [Math.min(255, v * 510), Math.min(255, v * 510 - 255), Math.max(0, 255 - v * 510), a]; }), l),
      solarize: (l) => applyToActive((d) => eachPixel(d, (r, g, b, a) => [r > 128 ? 255 - r : r, g > 128 ? 255 - g : g, b > 128 ? 255 - b : b, a]), l),
      edge: (l) =>
        applyToActive((d) => {
          const { width: w, height: h, data: p } = d;
          const copy = new Uint8ClampedArray(p);
          for (let y = 1; y < h - 1; y++)
            for (let x = 1; x < w - 1; x++) {
              const i = (y * w + x) * 4;
              const gx = -copy[i - 4] + copy[i + 4];
              const gy = -copy[i - w * 4] + copy[i + w * 4];
              const m = Math.min(255, Math.hypot(gx, gy));
              p[i] = m; p[i + 1] = m; p[i + 2] = m;
            }
        }, l),
    }),
    [applyToActive]
  );

  /* ---- drawing primitives ---- */
  const drawShape = useCallback(
    (ctx: CanvasRenderingContext2D, from: Point, to: Point, shape: string, dashed = false) => {
      const x1 = from.x, y1 = from.y, x2 = to.x, y2 = to.y;
      ctx.save();
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = Math.max(1, brushSize);
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      if (dashed) ctx.setLineDash([5, 4]);
      const w = x2 - x1, h = y2 - y1;
      ctx.beginPath();
      switch (shape) {
        case "line":
          ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
          break;
        case "arrow": {
          ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
          const ang = Math.atan2(y2 - y1, x2 - x1);
          const hl = 12 + brushSize;
          ctx.beginPath();
          ctx.moveTo(x2, y2);
          ctx.lineTo(x2 - hl * Math.cos(ang - 0.4), y2 - hl * Math.sin(ang - 0.4));
          ctx.lineTo(x2 - hl * Math.cos(ang + 0.4), y2 - hl * Math.sin(ang + 0.4));
          ctx.closePath(); ctx.fill();
          break;
        }
        case "rectangle":
          ctx.rect(x1, y1, w, h); ctx.stroke();
          break;
        case "ellipse":
          ctx.ellipse((x1 + x2) / 2, (y1 + y2) / 2, Math.abs(w / 2), Math.abs(h / 2), 0, 0, Math.PI * 2); ctx.stroke();
          break;
        case "triangle":
          ctx.moveTo((x1 + x2) / 2, y1); ctx.lineTo(x2, y2); ctx.lineTo(x1, y2); ctx.closePath(); ctx.stroke();
          break;
        case "right_triangle":
          ctx.moveTo(x1, y1); ctx.lineTo(x1, y2); ctx.lineTo(x2, y2); ctx.closePath(); ctx.stroke();
          break;
        case "romb":
          ctx.moveTo((x1 + x2) / 2, y1); ctx.lineTo(x2, (y1 + y2) / 2); ctx.lineTo((x1 + x2) / 2, y2); ctx.lineTo(x1, (y1 + y2) / 2); ctx.closePath(); ctx.stroke();
          break;
        case "parallelogram":
          ctx.moveTo(x1 + Math.abs(w) * 0.25, y1); ctx.lineTo(x2, y1); ctx.lineTo(x2 - Math.abs(w) * 0.25, y2); ctx.lineTo(x1, y2); ctx.closePath(); ctx.stroke();
          break;
        case "trapezoid":
          ctx.moveTo(x1 + Math.abs(w) * 0.2, y1); ctx.lineTo(x2 - Math.abs(w) * 0.2, y1); ctx.lineTo(x2, y2); ctx.lineTo(x1, y2); ctx.closePath(); ctx.stroke();
          break;
        case "plus": {
          const t = Math.min(Math.abs(w), Math.abs(h)) / 3;
          ctx.moveTo(x1 + t, y1); ctx.lineTo(x2 - t, y1); ctx.lineTo(x2 - t, y2 - (Math.abs(h) - t) / 2);
          ctx.lineTo(x2, y2 - (Math.abs(h) - t) / 2); ctx.lineTo(x2, y2 + (Math.abs(h) - t) / 2);
          ctx.lineTo(x2 - t, y2 + (Math.abs(h) - t) / 2); ctx.lineTo(x2 - t, y2); ctx.lineTo(x1 + t, y2);
          ctx.lineTo(x1 + t, y2 + (Math.abs(h) - t) / 2); ctx.lineTo(x1, y2 + (Math.abs(h) - t) / 2);
          ctx.lineTo(x1, y2 - (Math.abs(h) - t) / 2); ctx.lineTo(x1 + t, y2 - (Math.abs(h) - t) / 2);
          ctx.closePath(); ctx.stroke();
          break;
        }
        case "pentagon":
        case "hexagon":
        case "polygon": {
          const sides = shape === "pentagon" ? 5 : shape === "hexagon" ? 6 : 6;
          const cx = (x1 + x2) / 2, cy = (y1 + y2) / 2;
          const rx = Math.abs(w / 2), ry = Math.abs(h / 2);
          for (let i = 0; i <= sides; i++) {
            const a = -Math.PI / 2 + (i * 2 * Math.PI) / sides;
            const px = cx + rx * Math.cos(a), py = cy + ry * Math.sin(a);
            if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
          }
          ctx.closePath(); ctx.stroke();
          break;
        }
        case "star": {
          const cx = (x1 + x2) / 2, cy = (y1 + y2) / 2;
          const R = Math.min(Math.abs(w), Math.abs(h)) / 2, r2 = R * 0.4;
          for (let i = 0; i < 10; i++) {
            const a = -Math.PI / 2 + (i * Math.PI) / 5;
            const rad = i % 2 === 0 ? R : r2;
            const px = cx + rad * Math.cos(a), py = cy + rad * Math.sin(a);
            if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
          }
          ctx.closePath(); ctx.stroke();
          break;
        }
        case "heart": {
          const cx = (x1 + x2) / 2, cy = (y1 + y2) / 2;
          const sx = Math.abs(w) / 2, sy = Math.abs(h) / 2;
          ctx.moveTo(cx, cy + sy * 0.8);
          ctx.bezierCurveTo(cx - sx * 1.4, cy - sy * 0.4, cx - sx * 0.5, cy - sy * 1.2, cx, cy - sy * 0.35);
          ctx.bezierCurveTo(cx + sx * 0.5, cy - sy * 1.2, cx + sx * 1.4, cy - sy * 0.4, cx, cy + sy * 0.8);
          ctx.closePath(); ctx.stroke();
          break;
        }
        case "cylinder": {
          const rx = Math.abs(w / 2), ry = Math.min(Math.abs(h) / 4, 20);
          ctx.ellipse((x1 + x2) / 2, y1 + ry, rx, ry, 0, 0, Math.PI * 2);
          ctx.moveTo(x1, y1 + ry); ctx.lineTo(x1, y2 - ry);
          ctx.moveTo(x2, y1 + ry); ctx.lineTo(x2, y2 - ry);
          ctx.moveTo(x1, y2 - ry);
          ctx.bezierCurveTo(x1, y2 - ry + ry, x2, y2 - ry + ry, x2, y2 - ry);
          ctx.stroke();
          break;
        }
        case "moon": {
          const cx = (x1 + x2) / 2, cy = (y1 + y2) / 2;
          ctx.arc(cx, cy, Math.abs(w / 2), 0, Math.PI * 2);
          ctx.stroke();
          ctx.beginPath();
          ctx.arc(cx + Math.abs(w) * 0.22, cy - Math.abs(h) * 0.08, Math.abs(w / 2) * 0.92, 0, Math.PI * 2);
          ctx.stroke();
          break;
        }
        case "callout":
          ctx.rect(x1, y1, w, h * 0.7);
          ctx.moveTo(x1 + Math.abs(w) * 0.2, y1 + h * 0.7);
          ctx.lineTo(x1 + Math.abs(w) * 0.2, y2);
          ctx.lineTo(x1 + Math.abs(w) * 0.45, y1 + h * 0.7);
          ctx.stroke();
          break;
        case "human": {
          const cx = (x1 + x2) / 2;
          const top = Math.min(y1, y2);
          ctx.arc(cx, top + Math.abs(h) * 0.12, Math.abs(h) * 0.12, 0, Math.PI * 2); ctx.stroke();
          ctx.beginPath();
          ctx.moveTo(cx, top + Math.abs(h) * 0.24); ctx.lineTo(cx, top + Math.abs(h) * 0.62);
          ctx.moveTo(cx - Math.abs(w) * 0.25, top + Math.abs(h) * 0.38); ctx.lineTo(cx + Math.abs(w) * 0.25, top + Math.abs(h) * 0.38);
          ctx.moveTo(cx, top + Math.abs(h) * 0.62); ctx.lineTo(cx - Math.abs(w) * 0.25, y2);
          ctx.moveTo(cx, top + Math.abs(h) * 0.62); ctx.lineTo(cx + Math.abs(w) * 0.25, y2);
          ctx.stroke();
          break;
        }
        default:
          ctx.rect(x1, y1, w, h); ctx.stroke();
      }
      ctx.restore();
    },
    [brushSize, color]
  );

  /* ---- pointer interaction ---- */
  const drag = useRef<{ start: Point; last: Point; active: boolean; preview: boolean } | null>(null);

  const paintStroke = useCallback(
    (from: Point, to: Point, erase: boolean) => {
      const rt = active();
      if (!rt) return;
      const ctx = rt.canvas.getContext("2d")!;
      ctx.save();
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      if (erase) {
        ctx.globalCompositeOperation = "destination-out";
        ctx.lineWidth = brushSize * 3;
      } else {
        ctx.globalCompositeOperation = "source-over";
        ctx.strokeStyle = tool === "pencil" ? color : color;
        ctx.lineWidth = tool === "pencil" ? 1 : brushSize;
      }
      ctx.beginPath();
      ctx.moveTo(from.x, from.y);
      ctx.lineTo(to.x, to.y);
      ctx.stroke();
      ctx.restore();
    },
    [active, brushSize, color, tool]
  );

  const floodFill = useCallback(
    (pt: Point) => {
      const rt = active();
      if (!rt) return;
      const ctx = rt.canvas.getContext("2d")!;
      const img = ctx.getImageData(0, 0, rt.canvas.width, rt.canvas.height);
      const { width: w, height: h, data: p } = img;
      const sx = Math.floor(pt.x), sy = Math.floor(pt.y);
      if (sx < 0 || sy < 0 || sx >= w || sy >= h) return;
      const idx = (x: number, y: number) => (y * w + x) * 4;
      const start = idx(sx, sy);
      const target = [p[start], p[start + 1], p[start + 2], p[start + 3]];
      const { r, g, b } = hexToRgb(color);
      const fill = [r, g, b, 255];
      if (target.every((v, i) => Math.abs(v - fill[i]) < 4)) return;
      const match = (i: number) =>
        Math.abs(p[i] - target[0]) < 24 &&
        Math.abs(p[i + 1] - target[1]) < 24 &&
        Math.abs(p[i + 2] - target[2]) < 24 &&
        Math.abs(p[i + 3] - target[3]) < 24;
      const stack: number[] = [sx, sy];
      const seen = new Uint8Array(w * h);
      while (stack.length) {
        const y = stack.pop()!;
        const x = stack.pop()!;
        if (x < 0 || y < 0 || x >= w || y >= h) continue;
        if (seen[y * w + x]) continue;
        const i = idx(x, y);
        if (!match(i)) continue;
        seen[y * w + x] = 1;
        p[i] = fill[0]; p[i + 1] = fill[1]; p[i + 2] = fill[2]; p[i + 3] = fill[3];
        stack.push(x + 1, y, x - 1, y, x, y + 1, x, y - 1);
      }
      ctx.putImageData(img, 0, 0);
    },
    [active, color]
  );

  const onPointerDown = useCallback(
    (e: React.PointerEvent<HTMLCanvasElement>) => {
      const pt = toImageCoords(e.clientX, e.clientY);
      if (!pt) return;
      (e.target as HTMLElement).setPointerCapture?.(e.pointerId);
      if (tool === "pick_color") {
        const disp = displayRef.current!;
        const d = disp.getContext("2d")!.getImageData(Math.floor(pt.x), Math.floor(pt.y), 1, 1).data;
        setColor(rgbToHex(d[0], d[1], d[2]));
        setStatus("Color picked");
        return;
      }
      if (tool === "fill") {
        pushHistory();
        floodFill(pt);
        setStatus("Fill");
        syncMeta();
        return;
      }
      if (tool === "crop" || tool === "selection" || tool === "select") {
        drag.current = { start: pt, last: pt, active: true, preview: true };
        setSelection({ x: pt.x, y: pt.y, width: 0, height: 0 });
        return;
      }
      if (tool === "text") {
        const rt = active();
        if (!rt) return;
        const val = typeof window !== "undefined" ? window.prompt("Text:", "") : null;
        if (val) {
          pushHistory();
          const ctx = rt.canvas.getContext("2d")!;
          ctx.fillStyle = color;
          ctx.font = `${Math.max(12, brushSize * 4)}px Arial`;
          ctx.fillText(val, pt.x, pt.y);
          syncMeta();
        }
        return;
      }
      if (["blur", "sharpen", "desaturate", "bulge_pinch", "clone"].includes(tool)) {
        pushHistory();
        applyToActive(
          (d) => {
            const { width: w, data: p } = d;
            const radius = 18;
            const copy = new Uint8ClampedArray(p);
            for (let y = Math.floor(pt.y - radius); y <= pt.y + radius; y++)
              for (let x = Math.floor(pt.x - radius); x <= pt.x + radius; x++) {
                if (x < 0 || y < 0 || x >= w || y >= d.height) continue;
                if (Math.hypot(x - pt.x, y - pt.y) > radius) continue;
                const i = (y * w + x) * 4;
                if (tool === "desaturate") {
                  const v = 0.299 * copy[i] + 0.587 * copy[i + 1] + 0.114 * copy[i + 2];
                  p[i] = p[i + 1] = p[i + 2] = v;
                } else if (tool === "sharpen") {
                  for (let c = 0; c < 3; c++) {
                    const cur = copy[i + c];
                    const avg = (copy[i + c - 4] + copy[i + c + 4] + copy[i + c - w * 4] + copy[i + c + w * 4]) / 4;
                    p[i + c] = cur + (cur - avg) * 0.8;
                  }
                } else if (tool === "blur") {
                  for (let c = 0; c < 3; c++) {
                    p[i + c] = (copy[i + c] + copy[i + c - 4] + copy[i + c + 4] + copy[i + c - w * 4] + copy[i + c + w * 4]) / 5;
                  }
                }
              }
          },
          tool
        );
        syncMeta();
        return;
      }
      if (tool === "gradient") {
        drag.current = { start: pt, last: pt, active: true, preview: true };
        return;
      }
      if (tool === "shape") {
        drag.current = { start: pt, last: pt, active: true, preview: true };
        return;
      }
      // brush / pencil / erase
      pushHistory();
      drag.current = { start: pt, last: pt, active: true, preview: false };
      paintStroke(pt, { x: pt.x + 0.01, y: pt.y }, tool === "erase");
      composite();
    },
    [applyToActive, composite, floodFill, paintStroke, pushHistory, syncMeta, toImageCoords, tool]
  );

  const drawOverlay = useCallback(
    (pt: Point) => {
      const d = drag.current;
      if (!d) return;
      if (tool === "shape") drawShape(displayRef.current!.getContext("2d")!, d.start, pt, shapeTool, true);
      else if (tool === "gradient") {
        const ctx = displayRef.current!.getContext("2d")!;
        ctx.save();
        ctx.strokeStyle = "#ffffff";
        ctx.setLineDash([5, 4]);
        ctx.beginPath();
        ctx.moveTo(d.start.x, d.start.y);
        ctx.lineTo(pt.x, pt.y);
        ctx.stroke();
        ctx.restore();
      } else if (selection) {
        const ctx = displayRef.current!.getContext("2d")!;
        ctx.save();
        ctx.strokeStyle = "#ffffff";
        ctx.setLineDash([5, 4]);
        ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
        ctx.restore();
      }
    },
    [drawShape, selection, shapeTool, tool]
  );

  const onPointerMove = useCallback(
    (e: React.PointerEvent<HTMLCanvasElement>) => {
      const pt = toImageCoords(e.clientX, e.clientY);
      if (!pt) return;
      setMouse(pt);
      const d = drag.current;
      if (!d || !d.active) return;
      if (tool === "shape" || tool === "gradient") {
        d.last = pt;
        composite();
        if (tool === "shape") drawOverlay(pt);
        else {
          const ctx = displayRef.current!.getContext("2d")!;
          ctx.save();
          ctx.strokeStyle = "#fff";
          ctx.setLineDash([5, 4]);
          ctx.beginPath();
          ctx.moveTo(d.start.x, d.start.y);
          ctx.lineTo(pt.x, pt.y);
          ctx.stroke();
          ctx.restore();
        }
        return;
      }
      if (tool === "selection" || tool === "select" || tool === "crop") {
        const r: Rect = {
          x: Math.min(d.start.x, pt.x),
          y: Math.min(d.start.y, pt.y),
          width: Math.abs(pt.x - d.start.x),
          height: Math.abs(pt.y - d.start.y),
        };
        setSelection(r);
        composite();
        const ctx = displayRef.current!.getContext("2d")!;
        ctx.save();
        ctx.strokeStyle = "#f4f3f3";
        ctx.setLineDash([5, 4]);
        ctx.strokeRect(r.x, r.y, r.width, r.height);
        ctx.restore();
        return;
      }
      paintStroke(d.last, pt, tool === "erase");
      d.last = pt;
      composite();
    },
    [composite, drawOverlay, paintStroke, tool, toImageCoords]
  );

  const onPointerUp = useCallback(
    (e: React.PointerEvent<HTMLCanvasElement>) => {
      const d = drag.current;
      if (!d) return;
      const pt = toImageCoords(e.clientX, e.clientY) || d.last;
      if (tool === "shape") {
        const rt = active();
        if (rt) {
          pushHistory();
          drawShape(rt.canvas.getContext("2d")!, d.start, pt, shapeTool, false);
        }
      } else if (tool === "gradient") {
        const rt = active();
        if (rt) {
          pushHistory();
          const ctx = rt.canvas.getContext("2d")!;
          const grad = ctx.createLinearGradient(d.start.x, d.start.y, pt.x, pt.y);
          grad.addColorStop(0, color);
          grad.addColorStop(1, "rgba(255,255,255,0)");
          ctx.fillStyle = grad;
          ctx.fillRect(0, 0, rt.canvas.width, rt.canvas.height);
        }
      } else if (tool === "crop" && selection && selection.width > 2 && selection.height > 2) {
        cropTo(selection);
        setSelection(null);
      }
      drag.current = null;
      syncMeta();
    },
    [active, color, drawShape, pushHistory, selection, shapeTool, syncMeta, toImageCoords, tool]
  );

  /* ---- document operations ---- */
  const newDocument = useCallback(
    (w: number, h: number) => {
      layerRefs.current.clear();
      history.current = [];
      future.current = [];
      setWidth(w);
      setHeight(h);
      const id = layerSeq++;
      const rt: LayerRuntime = { id, name: "Brush #1", visible: true, opacity: 100, x: 0, y: 0, canvas: makeCanvas(w, h) };
      const ctx = rt.canvas.getContext("2d")!;
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(0, 0, w, h);
      layerRefs.current.set(id, rt);
      setActiveLayerId(id);
      setZoom(100);
      setSelection(null);
      const disp = displayRef.current;
      if (disp) {
        disp.width = w;
        disp.height = h;
      }
      setStatus(`New ${w}x${h} document`);
      syncMeta();
    },
    [syncMeta]
  );

  const cropTo = useCallback(
    (r: Rect) => {
      const x = Math.max(0, Math.round(r.x));
      const y = Math.max(0, Math.round(r.y));
      const w = Math.max(1, Math.round(r.width));
      const h = Math.max(1, Math.round(r.height));
      pushHistory();
      const next = new Map<number, LayerRuntime>();
      for (const [id, rt] of layerRefs.current) {
        const c = makeCanvas(w, h);
        const ctx = c.getContext("2d")!;
        ctx.drawImage(rt.canvas, x - rt.x, y - rt.y, w, h, 0, 0, w, h);
        next.set(id, { ...rt, canvas: c, x: 0, y: 0 });
      }
      layerRefs.current = next;
      setWidth(w);
      setHeight(h);
      const disp = displayRef.current;
      if (disp) {
        disp.width = w;
        disp.height = h;
      }
      setStatus("Cropped");
      syncMeta();
    },
    [pushHistory, syncMeta]
  );

  const resize = useCallback(
    (w: number, h: number) => {
      pushHistory();
      for (const rt of layerRefs.current.values()) {
        const c = makeCanvas(w, h);
        c.getContext("2d")!.drawImage(rt.canvas, 0, 0, w, h);
        rt.canvas = c;
      }
      setWidth(w);
      setHeight(h);
      const disp = displayRef.current;
      if (disp) {
        disp.width = w;
        disp.height = h;
      }
      syncMeta();
    },
    [pushHistory, syncMeta]
  );

  const rotate = useCallback(
    (deg: number) => {
      pushHistory();
      const rad = (deg * Math.PI) / 180;
      for (const rt of layerRefs.current.values()) {
        const sw = rt.canvas.width, sh = rt.canvas.height;
        const nw = deg % 180 === 0 ? sw : sh;
        const nh = deg % 180 === 0 ? sh : sw;
        const c = makeCanvas(nw, nh);
        const ctx = c.getContext("2d")!;
        ctx.translate(nw / 2, nh / 2);
        ctx.rotate(rad);
        ctx.drawImage(rt.canvas, -sw / 2, -sh / 2);
        rt.canvas = c;
      }
      if (deg % 180 !== 0) {
        const t = W; setWidth(H); setHeight(t);
        const disp = displayRef.current;
        if (disp) { disp.width = H; disp.height = W; }
      }
      syncMeta();
    },
    [H, W, pushHistory, syncMeta]
  );

  const flip = useCallback(
    (dir: "h" | "v") => {
      applyToActive((d) => {
        const { width: w, height: h, data: p } = d;
        const out = new Uint8ClampedArray(p.length);
        for (let y = 0; y < h; y++)
          for (let x = 0; x < w; x++) {
            const sx = dir === "h" ? w - 1 - x : x;
            const sy = dir === "v" ? h - 1 - y : y;
            const si = (sy * w + sx) * 4;
            const di = (y * w + x) * 4;
            out[di] = p[si]; out[di + 1] = p[si + 1]; out[di + 2] = p[si + 2]; out[di + 3] = p[si + 3];
          }
        p.set(out);
      }, dir === "h" ? "Flip horizontal" : "Flip vertical");
    },
    [applyToActive]
  );

  /* ---- layers ---- */
  const addLayer = useCallback(() => {
    pushHistory();
    const id = layerSeq++;
    const names = [...layerRefs.current.values()].length + 1;
    const rt: LayerRuntime = { id, name: `Layer #${names}`, visible: true, opacity: 100, x: 0, y: 0, canvas: makeCanvas(W, H) };
    layerRefs.current.set(id, rt);
    setActiveLayerId(id);
    syncMeta();
    setStatus("Layer added");
  }, [H, W, pushHistory, syncMeta]);

  const duplicateLayer = useCallback(() => {
    const rt = active();
    if (!rt) return;
    pushHistory();
    const id = layerSeq++;
    const c = makeCanvas(rt.canvas.width, rt.canvas.height);
    c.getContext("2d")!.drawImage(rt.canvas, 0, 0);
    layerRefs.current.set(id, { ...rt, id, name: `${rt.name} copy`, canvas: c });
    setActiveLayerId(id);
    syncMeta();
  }, [active, pushHistory, syncMeta]);

  const deleteLayer = useCallback(() => {
    if (layerRefs.current.size <= 1) return;
    pushHistory();
    layerRefs.current.delete(activeLayerId);
    const next = [...layerRefs.current.keys()].pop()!;
    setActiveLayerId(next);
    syncMeta();
  }, [activeLayerId, pushHistory, syncMeta]);

  const toggleLayerVisible = useCallback(
    (id: number) => {
      const rt = layerRefs.current.get(id);
      if (!rt) return;
      rt.visible = !rt.visible;
      syncMeta();
    },
    [syncMeta]
  );

  const clearLayer = useCallback(() => {
    const rt = active();
    if (!rt) return;
    pushHistory();
    rt.canvas.getContext("2d")!.clearRect(0, 0, rt.canvas.width, rt.canvas.height);
    syncMeta();
  }, [active, pushHistory, syncMeta]);

  const moveLayer = useCallback(
    (dir: "up" | "down") => {
      const entries = [...layerRefs.current.entries()];
      const idx = entries.findIndex(([id]) => id === activeLayerId);
      const swap = dir === "up" ? idx + 1 : idx - 1;
      if (swap < 0 || swap >= entries.length) return;
      [entries[idx], entries[swap]] = [entries[swap], entries[idx]];
      layerRefs.current = new Map(entries);
      syncMeta();
    },
    [activeLayerId, syncMeta]
  );

  const flatten = useCallback(() => {
    pushHistory();
    const rt = active();
    if (!rt) return;
    const ctx = rt.canvas.getContext("2d")!;
    ctx.clearRect(0, 0, rt.canvas.width, rt.canvas.height);
    for (const l of layerRefs.current.values()) {
      if (!l.visible) continue;
      ctx.globalAlpha = l.opacity / 100;
      ctx.drawImage(l.canvas, l.x, l.y);
    }
    ctx.globalAlpha = 1;
    const keep = rt;
    layerRefs.current = new Map([[keep.id, keep]]);
    setActiveLayerId(keep.id);
    syncMeta();
    setStatus("Flattened");
  }, [active, pushHistory, syncMeta]);

  /* ---- layer details ---- */
  const updateLayer = useCallback(
    (patch: Partial<Layer>) => {
      const rt = active();
      if (!rt) return;
      Object.assign(rt, patch);
      syncMeta();
    },
    [active, syncMeta]
  );

  /* ---- export ---- */
  const exportImage = useCallback(
    (format = "png") => {
      const c = makeCanvas(W, H);
      const ctx = c.getContext("2d")!;
      for (const rt of layerRefs.current.values()) {
        if (!rt.visible) continue;
        ctx.globalAlpha = rt.opacity / 100;
        ctx.drawImage(rt.canvas, rt.x, rt.y);
      }
      const url = c.toDataURL(`image/${format}`);
      const a = document.createElement("a");
      a.href = url;
      a.download = `export.${format}`;
      a.click();
      setStatus(`Exported ${format.toUpperCase()}`);
    },
    [H, W]
  );

  /* ---- zoom helpers ---- */
  const zoomIn = useCallback(() => setZoom((z) => Math.min(2000, Math.round(z * 1.2))), []);
  const zoomOut = useCallback(() => setZoom((z) => Math.max(10, Math.round(z / 1.2))), []);
  const zoomFit = useCallback(() => setZoom(100), []);
  const zoomOriginal = useCallback(() => setZoom(100), []);

  /* ---- size / resolution ---- */
  const pxSize = useMemo(() => {
    const dpi = parseInt(resolution, 10) || 72;
    return { w: ((W / dpi) * 2.54).toFixed(2), h: ((H / dpi) * 2.54).toFixed(2) };
  }, [W, H, resolution]);

  /* ---- form dialog helpers ---- */
  const openDialog = useCallback((d: DialogState) => setDialog(d), []);
  const closeDialog = useCallback(() => setDialog(null), []);

  return {
    // state
    width: W,
    height: H,
    layers: layerMeta,
    activeLayerId,
    tool,
    shapeTool,
    color,
    brushSize,
    pressure,
    zoom,
    mouse,
    grid,
    ruler,
    guides,
    fullscreen,
    resolution,
    dialog,
    status,
    selection,
    pxSize,
    setTool,
    setShapeTool,
    setColor,
    setBrushSize,
    setPressure,
    setZoom,
    setGrid,
    setRuler,
    setGuides,
    setResolution,
    setFullscreen,
    setStatus,
    openDialog,
    closeDialog,
    setLayerMeta,
    // canvas wiring
    displayRef,
    composite,
    onPointerDown,
    onPointerMove,
    onPointerUp,
    // ops
    undo,
    redo,
    pushHistory,
    newDocument,
    cropTo,
    resize,
    rotate,
    flip,
    addLayer,
    duplicateLayer,
    deleteLayer,
    toggleLayerVisible,
    clearLayer,
    moveLayer,
    flatten,
    updateLayer,
    setActiveLayerId,
    exportImage,
    zoomIn,
    zoomOut,
    zoomFit,
    zoomOriginal,
    effects,
    applyToActive,
    active,
    reRender,
  };
}

export type EditorApi = ReturnType<typeof useEditor>;

export const RESOLUTION_PRESETS = RESOLUTIONS;
export type { FieldDef, DialogState };

input.content:
/* Layout + component styles for the image editor */

.mp-app {
  display: flex;
  flex-direction: column;
  height: 100%;
  width: 100%;
}

/* ---------- main menu bar ---------- */
.mp-menubar {
  position: relative;
  z-index: 60;
  height: 30px;
  flex: 0 0 30px;
  background: var(--mp-menu-bg);
  display: flex;
  align-items: stretch;
  padding-left: 10px;
}
.mp-menubar ul {
  display: flex;
  list-style: none;
  margin: 0;
  padding: 0;
}
.mp-menubar li {
  position: relative;
}
.mp-menu-title {
  height: 30px;
  padding: 0 10px;
  background: transparent;
  border: none;
  color: var(--mp-text);
  display: flex;
  align-items: center;
}
.mp-menu-title:hover,
.mp-menu-title[data-open="true"] {
  background: #444;
}
.mp-menu-title[data-active="true"] {
  background: #5a5a5a;
}
.mp-dropdown {
  position: absolute;
  top: 30px;
  left: 0;
  min-width: 190px;
  background: var(--mp-menu-bg);
  border: 1px solid #555;
  padding: 4px 0;
  list-style: none;
  margin: 0;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.5);
  z-index: 70;
}
.mp-dropdown--nested {
  top: -5px;
  left: 100%;
}
.mp-menu-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 20px;
  justify-content: space-between;
  width: 100%;
  padding: 3px 12px;
  background: transparent;
  border: none;
  color: var(--mp-text);
  white-space: nowrap;
  text-align: left;
}
.mp-menu-item:hover {
  background: #444;
}
.mp-menu-item .mp-key {
  color: #a9b1b3;
  font-size: 12px;
  margin-left: auto;
}
.mp-menu-sep {
  height: 1px;
  background: #555;
  margin: 4px 6px;
}
.mp-menu-item .mp-sub-arrow {
  margin-left: 12px;
  color: #a9b1b3;
}

/* ---------- submenu / top bar ---------- */
.mp-submenu {
  flex: 0 0 40px;
  height: 40px;
  background: var(--mp-bar-bg);
  display: flex;
  align-items: center;
  padding: 0 5px;
  gap: 10px;
}
.mp-logo {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 110px;
  height: 30px;
  color: var(--mp-text);
  text-decoration: none;
  font-weight: 700;
  padding-left: 2px;
}
.mp-logo-badge {
  width: 30px;
  height: 30px;
  border-radius: 3px;
  display: block;
  flex: 0 0 auto;
}
.mp-attributes {
  display: flex;
  align-items: center;
  gap: 12px;
  height: 30px;
  flex: 1 1 auto;
}
.mp-attr {
  display: flex;
  align-items: center;
  gap: 5px;
}
.mp-attr > label {
  color: var(--mp-text);
}
.mp-number {
  display: inline-flex;
  position: relative;
}
.mp-number input {
  width: 60px;
  height: 23px;
  background: var(--mp-input-bg);
  color: var(--mp-text);
  border: 1px solid var(--mp-input-border);
  padding: 0 20px 0 5px;
  -moz-appearance: textfield;
}
.mp-number input::-webkit-outer-spin-button,
.mp-number input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}
.mp-number .mp-spin {
  position: absolute;
  right: 1px;
  width: 20px;
  height: 50%;
  border: none;
  background: #444b4d;
  color: #ddd;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 8px;
  line-height: 1;
  padding: 0;
}
.mp-number .mp-spin.up {
  top: 1px;
}
.mp-number .mp-spin.down {
  bottom: 1px;
}
.mp-number .mp-spin:hover {
  background: #5a6264;
}
.mp-toggle {
  height: 23px;
  padding: 0 10px;
  background: #444b4d;
  border: 1px solid var(--mp-input-border);
  color: var(--mp-text);
}
.mp-toggle[aria-pressed="true"] {
  background: var(--mp-highlight);
  color: #111;
}

/* ---------- workspace ---------- */
.mp-workspace {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  position: relative;
}

/* left toolbar */
.mp-toolbar {
  flex: 0 0 40px;
  width: 40px;
  background: var(--mp-bar-bg);
  padding: 5px 5px 5px 5px;
  display: flex;
  flex-direction: column;
  align-items: center;
  overflow-y: auto;
  overflow-x: hidden;
}
.mp-tool {
  width: 30px;
  height: 25px;
  flex: 0 0 25px;
  margin-bottom: 5px;
  background: var(--mp-block-bg);
  color: #dfe3e4;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}
.mp-tool:hover {
  background: var(--mp-active);
}
.mp-tool.active {
  background: var(--mp-accent);
  color: #111;
}

/* canvas area */
.mp-canvas-area {
  flex: 1 1 auto;
  min-width: 0;
  position: relative;
  overflow: auto;
  background: var(--mp-bg);
  display: flex;
  align-items: center;
  justify-content: center;
}
.mp-canvas-stage {
  position: relative;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.25);
}
.mp-canvas-stage canvas {
  display: block;
  touch-action: none;
  cursor: crosshair;
}
.mp-checker {
  position: absolute;
  inset: 0;
  z-index: -1;
  background-image: linear-gradient(45deg, #cfcfcf 25%, transparent 25%),
    linear-gradient(-45deg, #cfcfcf 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #cfcfcf 75%),
    linear-gradient(-45deg, transparent 75%, #cfcfcf 75%);
  background-size: 16px 16px;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0px;
  background-color: #fff;
}

/* ---------- right sidebar ---------- */
.mp-sidebar {
  flex: 0 0 200px;
  width: 200px;
  background: var(--mp-bg);
  overflow-y: auto;
  overflow-x: hidden;
  padding: 0 5px;
}
.mp-block {
  background: var(--mp-block-bg);
  border-radius: 4px;
  margin: 5px 0;
  overflow: hidden;
}
.mp-block > h2 {
  margin: 0;
  height: 24px;
  background: var(--mp-header-bg);
  color: var(--mp-text);
  font-size: 14.3px;
  font-weight: 700;
  padding: 2px 5px 2px 6px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  user-select: none;
}
.mp-block-body {
  padding: 7.5px 5px;
}
.mp-block.collapsed .mp-block-body {
  display: none;
}
.mp-caret {
  font-size: 9px;
  line-height: 1;
  transition: transform 0.12s ease;
}
.mp-caret.up {
  transform: rotate(180deg);
}

/* preview */
.mp-preview-wrap {
  height: 100px;
  margin: 5px;
  background-color: #aaa;
  background-image: linear-gradient(45deg, #999 25%, transparent 25%),
    linear-gradient(-45deg, #999 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #999 75%),
    linear-gradient(-45deg, transparent 75%, #999 75%);
  background-size: 12px 12px;
  background-position: 0 0, 0 6px, 6px -6px, -6px 0px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.mp-preview-wrap canvas {
  max-width: 100%;
  max-height: 100%;
  display: block;
}
.mp-preview-details {
  padding: 0 5px 5px;
}
.mp-preview-buttons {
  display: flex;
  gap: 4px;
  margin-bottom: 5px;
}
.mp-mini-btn {
  height: 20px;
  min-width: 22px;
  padding: 0 4px;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: var(--mp-text);
  font-size: 12px;
}
.mp-mini-btn:hover {
  background: #3c4547;
}

/* colors */
.mp-color-head {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 7px;
}
.mp-color-preview {
  width: 30px;
  height: 30px;
  border: 1px solid #222;
  flex: 0 0 auto;
}
.mp-color-tabs {
  display: flex;
  gap: 4px;
  margin-left: auto;
}
.mp-color-tab {
  width: 27px;
  height: 24px;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: #dfe3e4;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}
.mp-color-tab[aria-pressed="true"] {
  background: #606a6c;
}
.mp-color-main {
  display: flex;
  gap: 5px;
}
.mp-sv {
  position: relative;
  flex: 1 1 auto;
  height: 110px;
  cursor: crosshair;
}
.mp-sv canvas {
  width: 100%;
  height: 100%;
  display: block;
  border-radius: 2px;
}
.mp-hue {
  flex: 0 0 auto;
  width: 22px;
  height: 110px;
  position: relative;
  cursor: crosshair;
  border-radius: 2px;
}
.mp-hue canvas {
  width: 100%;
  height: 100%;
  display: block;
  border-radius: 2px;
}
.mp-sv-cursor,
.mp-hue-cursor {
  position: absolute;
  width: 10px;
  height: 10px;
  border: 2px solid #fff;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 2px #000;
  pointer-events: none;
}
.mp-hex-row {
  display: flex;
  align-items: stretch;
  margin-top: 6px;
}
.mp-hex-row > span {
  background: var(--mp-block-bg);
  padding: 3px 5px;
  color: var(--mp-text);
}
.mp-hex-row input {
  flex: 1 1 auto;
  min-width: 0;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: var(--mp-text);
  padding: 3px 5px;
}
.mp-channels {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.mp-channel-row {
  display: flex;
  align-items: center;
  gap: 5px;
}
.mp-channel-row label {
  width: 12px;
}
.mp-channel-row input[type="text"] {
  width: 34px;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: var(--mp-text);
  padding: 1px 3px;
}
.mp-channel-row input[type="range"] {
  flex: 1 1 auto;
}
.mp-swatches {
  display: grid;
  grid-template-columns: repeat(10, 1fr);
  gap: 2px;
}
.mp-swatch {
  aspect-ratio: 1;
  border: 1px solid #222;
  padding: 0;
}

/* information */
.mp-info {
  display: grid;
  grid-template-columns: 82px 1fr;
  gap: 2px 4px;
  line-height: 1.4;
}
.mp-info dt {
  color: var(--mp-text);
}
.mp-info dd {
  margin: 0;
  color: #cfe8ff;
}

/* layer details */
.mp-details-body {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.mp-detail-row {
  display: flex;
  align-items: center;
  gap: 4px;
}
.mp-detail-row > span:first-child {
  flex: 0 0 46px;
}
.mp-detail-row .mp-number {
  flex: 1 1 auto;
}
.mp-detail-row .mp-number input {
  width: 100%;
}
.mp-reset-btn {
  flex: 0 0 auto;
  width: 20px;
  height: 19px;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: #cfd3d4;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}
.mp-details-sep {
  height: 1px;
  background: #3a4143;
  margin: 3px 0;
}
.mp-detail-color input {
  flex: 1 1 auto;
  min-width: 0;
  height: 19px;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: var(--mp-text);
  padding: 0 5px;
  cursor: pointer;
}

/* layers */
.mp-layer-actions {
  display: flex;
  gap: 4px;
  margin-bottom: 6px;
}
.mp-layer-list {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-height: 100px;
  max-height: 300px;
  overflow-y: auto;
}
.mp-layer-row {
  display: flex;
  align-items: center;
  gap: 2px;
}
.mp-layer-vis {
  width: 22px;
  height: 22px;
  flex: 0 0 auto;
  background: transparent;
  border: none;
  color: #dfe3e4;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}
.mp-layer-del {
  width: 22px;
  height: 22px;
  flex: 0 0 auto;
  background: transparent;
  border: none;
  color: #ef9a9a;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}
.mp-layer-name {
  flex: 1 1 auto;
  min-width: 0;
  height: 22px;
  padding: 0 5px;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: var(--mp-text);
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mp-layer-row.active .mp-layer-name {
  background: var(--mp-highlight);
  color: #111;
}

/* ---------- dialogs ---------- */
.mp-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.35);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: 12vh;
  z-index: 200;
}
.mp-dialog {
  background: var(--mp-block-bg);
  border-radius: 4px;
  min-width: 300px;
  max-width: 560px;
  max-height: 76vh;
  display: flex;
  flex-direction: column;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.6);
}
.mp-dialog > header {
  position: relative;
  height: 37px;
  background: var(--mp-header-bg);
  display: flex;
  align-items: center;
  padding: 0 12px;
  border-radius: 4px 4px 0 0;
}
.mp-dialog > header h2 {
  margin: 0;
  font-size: 15px;
  font-weight: 700;
  color: var(--mp-text);
}
.mp-dialog-close {
  position: absolute;
  top: 0;
  right: 0;
  width: 37px;
  height: 37px;
  background: transparent;
  border: none;
  color: #ccc;
  font-size: 20px;
  line-height: 1;
}
.mp-dialog-close:hover {
  color: #fff;
}
.mp-dialog-body {
  padding: 12px 16px;
  overflow: auto;
}
.mp-dialog table {
  border-collapse: collapse;
  width: 100%;
}
.mp-dialog th,
.mp-dialog td {
  text-align: left;
  padding: 4px 6px;
  vertical-align: middle;
  font-size: 13px;
}
.mp-dialog th {
  white-space: nowrap;
  font-weight: 700;
  width: 1%;
}
.mp-dialog td input[type="text"],
.mp-dialog td input[type="number"] {
  width: 100%;
  max-width: 200px;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: var(--mp-text);
  padding: 3px 6px;
}
.mp-dialog footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 10px 16px 14px;
}
.mp-dialog-btn {
  min-width: 64px;
  padding: 5px 14px;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: var(--mp-text);
}
.mp-dialog-btn:hover {
  background: #3c4547;
}
.mp-dialog-btn.primary {
  background: var(--mp-accent);
  color: #111;
}

.mp-radio-group {
  display: flex;
  flex-direction: column;
}
.mp-radio-group label {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 2px 0;
}
.mp-scroll-box {
  max-height: 200px;
  overflow: auto;
  padding: 4px 6px;
  background: #3d4345;
  border: 1px solid var(--mp-input-border);
}
.mp-radio-group.bordered {
  border: 1px solid #6a7274;
  padding: 4px 6px;
}
.mp-check {
  display: flex;
  align-items: center;
  gap: 6px;
}

.mp-about-body {
  text-align: center;
}
.mp-about-body img {
  width: 72px;
  height: 72px;
  margin: 0 auto 10px;
  display: block;
}
.mp-about-body table {
  width: auto;
  margin: 0 auto;
}

/* fullscreen */
.mp-app.mp-fullscreen .mp-menubar,
.mp-app.mp-fullscreen .mp-submenu {
  display: none;
}

/* ---------- responsive ---------- */
.mp-mobile-bar {
  display: none;
}
.mp-hamburger {
  width: 50px;
  height: 50px;
  flex: 0 0 50px;
  background: var(--mp-menu-bg);
  border: none;
  color: var(--mp-text);
  display: flex;
  align-items: center;
  justify-content: center;
}
.mp-hamburger .mp-bars {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.mp-hamburger .mp-bars span {
  display: block;
  width: 20px;
  height: 2px;
  background: var(--mp-text);
}
.mp-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.4);
  z-index: 80;
}

@media (max-width: 600px) {
  .mp-mobile-bar {
    display: flex;
    align-items: stretch;
    height: 50px;
    flex: 0 0 50px;
    background: var(--mp-menu-bg);
    gap: 0;
  }
  .mp-menubar {
    height: auto;
    min-height: 50px;
    flex: 0 0 auto;
    flex-wrap: wrap;
    padding: 0;
    align-items: stretch;
  }
  .mp-menubar ul {
    flex-wrap: wrap;
    height: 50px;
    align-items: center;
    overflow: hidden;
  }
  .mp-submenu {
    height: 51px;
    flex: 0 0 51px;
    gap: 5px;
    padding: 0 5px;
  }
  .mp-logo {
    width: 80px;
  }
  .mp-logo span:last-child {
    display: none;
  }
  .mp-attributes {
    gap: 6px;
    overflow: hidden;
  }
  .mp-toolbar {
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    z-index: 90;
    transform: translateX(-100%);
    transition: transform 0.2s ease;
    padding-top: 5px;
  }
  .mp-toolbar.open {
    transform: translateX(0);
    box-shadow: 4px 0 12px rgba(0, 0, 0, 0.5);
  }
  .mp-sidebar {
    position: absolute;
    right: 0;
    top: 0;
    bottom: 0;
    z-index: 90;
    transform: translateX(100%);
    transition: transform 0.2s ease;
    width: 200px;
    flex-basis: 200px;
  }
  .mp-sidebar.open {
    transform: translateX(0);
    box-shadow: -4px 0 12px rgba(0, 0, 0, 0.5);
  }
  .mp-dialog {
    max-width: 92vw;
  }
}

toolUseResult.content:
/* Layout + component styles for the image editor */

.mp-app {
  display: flex;
  flex-direction: column;
  height: 100%;
  width: 100%;
}

/* ---------- main menu bar ---------- */
.mp-menubar {
  position: relative;
  z-index: 60;
  height: 30px;
  flex: 0 0 30px;
  background: var(--mp-menu-bg);
  display: flex;
  align-items: stretch;
  padding-left: 10px;
}
.mp-menubar ul {
  display: flex;
  list-style: none;
  margin: 0;
  padding: 0;
}
.mp-menubar li {
  position: relative;
}
.mp-menu-title {
  height: 30px;
  padding: 0 10px;
  background: transparent;
  border: none;
  color: var(--mp-text);
  display: flex;
  align-items: center;
}
.mp-menu-title:hover,
.mp-menu-title[data-open="true"] {
  background: #444;
}
.mp-menu-title[data-active="true"] {
  background: #5a5a5a;
}
.mp-dropdown {
  position: absolute;
  top: 30px;
  left: 0;
  min-width: 190px;
  background: var(--mp-menu-bg);
  border: 1px solid #555;
  padding: 4px 0;
  list-style: none;
  margin: 0;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.5);
  z-index: 70;
}
.mp-dropdown--nested {
  top: -5px;
  left: 100%;
}
.mp-menu-item {
  position: relative;
  display: flex;
  align-items: center;
  gap: 20px;
  justify-content: space-between;
  width: 100%;
  padding: 3px 12px;
  background: transparent;
  border: none;
  color: var(--mp-text);
  white-space: nowrap;
  text-align: left;
}
.mp-menu-item:hover {
  background: #444;
}
.mp-menu-item .mp-key {
  color: #a9b1b3;
  font-size: 12px;
  margin-left: auto;
}
.mp-menu-sep {
  height: 1px;
  background: #555;
  margin: 4px 6px;
}
.mp-menu-item .mp-sub-arrow {
  margin-left: 12px;
  color: #a9b1b3;
}

/* ---------- submenu / top bar ---------- */
.mp-submenu {
  flex: 0 0 40px;
  height: 40px;
  background: var(--mp-bar-bg);
  display: flex;
  align-items: center;
  padding: 0 5px;
  gap: 10px;
}
.mp-logo {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 110px;
  height: 30px;
  color: var(--mp-text);
  text-decoration: none;
  font-weight: 700;
  padding-left: 2px;
}
.mp-logo-badge {
  width: 30px;
  height: 30px;
  border-radius: 3px;
  display: block;
  flex: 0 0 auto;
}
.mp-attributes {
  display: flex;
  align-items: center;
  gap: 12px;
  height: 30px;
  flex: 1 1 auto;
}
.mp-attr {
  display: flex;
  align-items: center;
  gap: 5px;
}
.mp-attr > label {
  color: var(--mp-text);
}
.mp-number {
  display: inline-flex;
  position: relative;
}
.mp-number input {
  width: 60px;
  height: 23px;
  background: var(--mp-input-bg);
  color: var(--mp-text);
  border: 1px solid var(--mp-input-border);
  padding: 0 20px 0 5px;
  -moz-appearance: textfield;
}
.mp-number input::-webkit-outer-spin-button,
.mp-number input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}
.mp-number .mp-spin {
  position: absolute;
  right: 1px;
  width: 20px;
  height: 50%;
  border: none;
  background: #444b4d;
  color: #ddd;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 8px;
  line-height: 1;
  padding: 0;
}
.mp-number .mp-spin.up {
  top: 1px;
}
.mp-number .mp-spin.down {
  bottom: 1px;
}
.mp-number .mp-spin:hover {
  background: #5a6264;
}
.mp-toggle {
  height: 23px;
  padding: 0 10px;
  background: #444b4d;
  border: 1px solid var(--mp-input-border);
  color: var(--mp-text);
}
.mp-toggle[aria-pressed="true"] {
  background: var(--mp-highlight);
  color: #111;
}

/* ---------- workspace ---------- */
.mp-workspace {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  position: relative;
}

/* left toolbar */
.mp-toolbar {
  flex: 0 0 40px;
  width: 40px;
  background: var(--mp-bar-bg);
  padding: 5px 5px 5px 5px;
  display: flex;
  flex-direction: column;
  align-items: center;
  overflow-y: auto;
  overflow-x: hidden;
}
.mp-tool {
  width: 30px;
  height: 25px;
  flex: 0 0 25px;
  margin-bottom: 5px;
  background: var(--mp-block-bg);
  color: #dfe3e4;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}
.mp-tool:hover {
  background: var(--mp-active);
}
.mp-tool.active {
  background: var(--mp-accent);
  color: #111;
}

/* canvas area */
.mp-canvas-area {
  flex: 1 1 auto;
  min-width: 0;
  position: relative;
  overflow: auto;
  background: var(--mp-bg);
  display: flex;
  align-items: center;
  justify-content: center;
}
.mp-canvas-stage {
  position: relative;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.25);
}
.mp-canvas-stage canvas {
  display: block;
  touch-action: none;
  cursor: crosshair;
}
.mp-checker {
  position: absolute;
  inset: 0;
  z-index: -1;
  background-image: linear-gradient(45deg, #cfcfcf 25%, transparent 25%),
    linear-gradient(-45deg, #cfcfcf 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #cfcfcf 75%),
    linear-gradient(-45deg, transparent 75%, #cfcfcf 75%);
  background-size: 16px 16px;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0px;
  background-color: #fff;
}

/* ---------- right sidebar ---------- */
.mp-sidebar {
  flex: 0 0 200px;
  width: 200px;
  background: var(--mp-bg);
  overflow-y: auto;
  overflow-x: hidden;
  padding: 0 5px;
}
.mp-block {
  background: var(--mp-block-bg);
  border-radius: 4px;
  margin: 5px 0;
  overflow: hidden;
}
.mp-block > h2 {
  margin: 0;
  height: 24px;
  background: var(--mp-header-bg);
  color: var(--mp-text);
  font-size: 14.3px;
  font-weight: 700;
  padding: 2px 5px 2px 6px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  user-select: none;
}
.mp-block-body {
  padding: 7.5px 5px;
}
.mp-block.collapsed .mp-block-body {
  display: none;
}
.mp-caret {
  font-size: 9px;
  line-height: 1;
  transition: transform 0.12s ease;
}
.mp-caret.up {
  transform: rotate(180deg);
}

/* preview */
.mp-preview-wrap {
  height: 100px;
  margin: 5px;
  background-color: #aaa;
  background-image: linear-gradient(45deg, #999 25%, transparent 25%),
    linear-gradient(-45deg, #999 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #999 75%),
    linear-gradient(-45deg, transparent 75%, #999 75%);
  background-size: 12px 12px;
  background-position: 0 0, 0 6px, 6px -6px, -6px 0px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.mp-preview-wrap canvas {
  max-width: 100%;
  max-height: 100%;
  display: block;
}
.mp-preview-details {
  padding: 0 5px 5px;
}
.mp-preview-buttons {
  display: flex;
  gap: 4px;
  margin-bottom: 5px;
}
.mp-mini-btn {
  height: 20px;
  min-width: 22px;
  padding: 0 4px;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: var(--mp-text);
  font-size: 12px;
}
.mp-mini-btn:hover {
  background: #3c4547;
}

/* colors */
.mp-color-head {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 7px;
}
.mp-color-preview {
  width: 30px;
  height: 30px;
  border: 1px solid #222;
  flex: 0 0 auto;
}
.mp-color-tabs {
  display: flex;
  gap: 4px;
  margin-left: auto;
}
.mp-color-tab {
  width: 27px;
  height: 24px;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: #dfe3e4;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}
.mp-color-tab[aria-pressed="true"] {
  background: #606a6c;
}
.mp-color-main {
  display: flex;
  gap: 5px;
}
.mp-sv {
  position: relative;
  flex: 1 1 auto;
  height: 110px;
  cursor: crosshair;
}
.mp-sv canvas {
  width: 100%;
  height: 100%;
  display: block;
  border-radius: 2px;
}
.mp-hue {
  flex: 0 0 auto;
  width: 22px;
  height: 110px;
  position: relative;
  cursor: crosshair;
  border-radius: 2px;
}
.mp-hue canvas {
  width: 100%;
  height: 100%;
  display: block;
  border-radius: 2px;
}
.mp-sv-cursor,
.mp-hue-cursor {
  position: absolute;
  width: 10px;
  height: 10px;
  border: 2px solid #fff;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 2px #000;
  pointer-events: none;
}
.mp-hex-row {
  display: flex;
  align-items: stretch;
  margin-top: 6px;
}
.mp-hex-row > span {
  background: var(--mp-block-bg);
  padding: 3px 5px;
  color: var(--mp-text);
}
.mp-hex-row input {
  flex: 1 1 auto;
  min-width: 0;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: var(--mp-text);
  padding: 3px 5px;
}
.mp-channels {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.mp-channel-row {
  display: flex;
  align-items: center;
  gap: 5px;
}
.mp-channel-row label {
  width: 12px;
}
.mp-channel-row input[type="text"] {
  width: 34px;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: var(--mp-text);
  padding: 1px 3px;
}
.mp-channel-row input[type="range"] {
  flex: 1 1 auto;
}
.mp-swatches {
  display: grid;
  grid-template-columns: repeat(10, 1fr);
  gap: 2px;
}
.mp-swatch {
  aspect-ratio: 1;
  border: 1px solid #222;
  padding: 0;
}

/* information */
.mp-info {
  display: grid;
  grid-template-columns: 82px 1fr;
  gap: 2px 4px;
  line-height: 1.4;
}
.mp-info dt {
  color: var(--mp-text);
}
.mp-info dd {
  margin: 0;
  color: #cfe8ff;
}

/* layer details */
.mp-details-body {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.mp-detail-row {
  display: flex;
  align-items: center;
  gap: 4px;
}
.mp-detail-row > span:first-child {
  flex: 0 0 46px;
}
.mp-detail-row .mp-number {
  flex: 1 1 auto;
}
.mp-detail-row .mp-number input {
  width: 100%;
}
.mp-reset-btn {
  flex: 0 0 auto;
  width: 20px;
  height: 19px;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: #cfd3d4;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}
.mp-details-sep {
  height: 1px;
  background: #3a4143;
  margin: 3px 0;
}
.mp-detail-color input {
  flex: 1 1 auto;
  min-width: 0;
  height: 19px;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: var(--mp-text);
  padding: 0 5px;
  cursor: pointer;
}

/* layers */
.mp-layer-actions {
  display: flex;
  gap: 4px;
  margin-bottom: 6px;
}
.mp-layer-list {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-height: 100px;
  max-height: 300px;
  overflow-y: auto;
}
.mp-layer-row {
  display: flex;
  align-items: center;
  gap: 2px;
}
.mp-layer-vis {
  width: 22px;
  height: 22px;
  flex: 0 0 auto;
  background: transparent;
  border: none;
  color: #dfe3e4;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}
.mp-layer-del {
  width: 22px;
  height: 22px;
  flex: 0 0 auto;
  background: transparent;
  border: none;
  color: #ef9a9a;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}
.mp-layer-name {
  flex: 1 1 auto;
  min-width: 0;
  height: 22px;
  padding: 0 5px;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: var(--mp-text);
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mp-layer-row.active .mp-layer-name {
  background: var(--mp-highlight);
  color: #111;
}

/* ---------- dialogs ---------- */
.mp-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.35);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: 12vh;
  z-index: 200;
}
.mp-dialog {
  background: var(--mp-block-bg);
  border-radius: 4px;
  min-width: 300px;
  max-width: 560px;
  max-height: 76vh;
  display: flex;
  flex-direction: column;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.6);
}
.mp-dialog > header {
  position: relative;
  height: 37px;
  background: var(--mp-header-bg);
  display: flex;
  align-items: center;
  padding: 0 12px;
  border-radius: 4px 4px 0 0;
}
.mp-dialog > header h2 {
  margin: 0;
  font-size: 15px;
  font-weight: 700;
  color: var(--mp-text);
}
.mp-dialog-close {
  position: absolute;
  top: 0;
  right: 0;
  width: 37px;
  height: 37px;
  background: transparent;
  border: none;
  color: #ccc;
  font-size: 20px;
  line-height: 1;
}
.mp-dialog-close:hover {
  color: #fff;
}
.mp-dialog-body {
  padding: 12px 16px;
  overflow: auto;
}
.mp-dialog table {
  border-collapse: collapse;
  width: 100%;
}
.mp-dialog th,
.mp-dialog td {
  text-align: left;
  padding: 4px 6px;
  vertical-align: middle;
  font-size: 13px;
}
.mp-dialog th {
  white-space: nowrap;
  font-weight: 700;
  width: 1%;
}
.mp-dialog td input[type="text"],
.mp-dialog td input[type="number"] {
  width: 100%;
  max-width: 200px;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: var(--mp-text);
  padding: 3px 6px;
}
.mp-dialog footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 10px 16px 14px;
}
.mp-dialog-btn {
  min-width: 64px;
  padding: 5px 14px;
  background: var(--mp-input-bg);
  border: 1px solid var(--mp-input-border);
  color: var(--mp-text);
}
.mp-dialog-btn:hover {
  background: #3c4547;
}
.mp-dialog-btn.primary {
  background: var(--mp-accent);
  color: #111;
}

.mp-radio-group {
  display: flex;
  flex-direction: column;
}
.mp-radio-group label {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 2px 0;
}
.mp-scroll-box {
  max-height: 200px;
  overflow: auto;
  padding: 4px 6px;
  background: #3d4345;
  border: 1px solid var(--mp-input-border);
}
.mp-radio-group.bordered {
  border: 1px solid #6a7274;
  padding: 4px 6px;
}
.mp-check {
  display: flex;
  align-items: center;
  gap: 6px;
}

.mp-about-body {
  text-align: center;
}
.mp-about-body img {
  width: 72px;
  height: 72px;
  margin: 0 auto 10px;
  display: block;
}
.mp-about-body table {
  width: auto;
  margin: 0 auto;
}

/* fullscreen */
.mp-app.mp-fullscreen .mp-menubar,
.mp-app.mp-fullscreen .mp-submenu {
  display: none;
}

/* ---------- responsive ---------- */
.mp-mobile-bar {
  display: none;
}
.mp-hamburger {
  width: 50px;
  height: 50px;
  flex: 0 0 50px;
  background: var(--mp-menu-bg);
  border: none;
  color: var(--mp-text);
  display: flex;
  align-items: center;
  justify-content: center;
}
.mp-hamburger .mp-bars {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.mp-hamburger .mp-bars span {
  display: block;
  width: 20px;
  height: 2px;
  background: var(--mp-text);
}
.mp-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.4);
  z-index: 80;
}

@media (max-width: 600px) {
  .mp-mobile-bar {
    display: flex;
    align-items: stretch;
    height: 50px;
    flex: 0 0 50px;
    background: var(--mp-menu-bg);
    gap: 0;
  }
  .mp-menubar {
    height: auto;
    min-height: 50px;
    flex: 0 0 auto;
    flex-wrap: wrap;
    padding: 0;
    align-items: stretch;
  }
  .mp-menubar ul {
    flex-wrap: wrap;
    height: 50px;
    align-items: center;
    overflow: hidden;
  }
  .mp-submenu {
    height: 51px;
    flex: 0 0 51px;
    gap: 5px;
    padding: 0 5px;
  }
  .mp-logo {
    width: 80px;
  }
  .mp-logo span:last-child {
    display: none;
  }
  .mp-attributes {
    gap: 6px;
    overflow: hidden;
  }
  .mp-toolbar {
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    z-index: 90;
    transform: translateX(-100%);
    transition: transform 0.2s ease;
    padding-top: 5px;
  }
  .mp-toolbar.open {
    transform: translateX(0);
    box-shadow: 4px 0 12px rgba(0, 0, 0, 0.5);
  }
  .mp-sidebar {
    position: absolute;
    right: 0;
    top: 0;
    bottom: 0;
    z-index: 90;
    transform: translateX(100%);
    transition: transform 0.2s ease;
    width: 200px;
    flex-basis: 200px;
  }
  .mp-sidebar.open {
    transform: translateX(0);
    box-shadow: -4px 0 12px rgba(0, 0, 0, 0.5);
  }
  .mp-dialog {
    max-width: 92vw;
  }
}

