import type { EditorApi } from "@/editor/useEditor";
import { NumberInput } from "./NumberInput";
import { LogoBadge } from "./LogoBadge";
import { cn } from "@/utils/cn";

interface Props {
  editor: EditorApi;
}

export function TopBar({ editor }: Props) {
  return (
    <div className="mp-submenu">
      <a
        className="mp-logo"
        href="#"
        onClick={(e) => {
          e.preventDefault();
          editor.setStatus("miniPaint");
        }}
      >
        <LogoBadge />
        <span>miniPaint</span>
      </a>
      <div className="mp-attributes" id="action_attributes">
        <div className="mp-attr">
          <label htmlFor="attr-size" className="mp-sr-only">
            Size:
          </label>
          <span aria-hidden="true">Size:</span>
          <NumberInput
            id="attr-size"
            ariaLabel="Size:"
            value={editor.brushSize}
            min={1}
            max={200}
            onChange={(v) => editor.setBrushSize(Math.max(1, Math.min(200, v)))}
          />
