async (page) => {
  const c = page.locator('.mp-canvas-stage canvas');
  const box = await c.boundingBox();
  await page.mouse.move(box.x + 80, box.y + 80);
  await page.mouse.down();
  await page.mouse.move(box.x + 260, box.y + 220, { steps: 8 });
  await page.mouse.up();
  await page.waitForTimeout(200);
  await page.screenshot({ path: '.playwright-mcp/shape-test.png', scale: 'css' });
  // also test undo
  await page.keyboard.press('Control+z');
  await page.waitForTimeout(200);
  await page.screenshot({ path: '.playwright-mcp/undo-test.png', scale: 'css' });
  return 'ok';
}

