() => {
  const out = {};
  out.localStorageKeys = Object.keys(localStorage);
  // Try Quick Save (F9)
  const before = { ...localStorage };
  try {
    const ev = new KeyboardEvent('keydown', { key: 'F9', code: 'F9', bubbles: true });
    document.dispatchEvent(ev);
  } catch(e) { out.err = String(e); }
  out.afterKeys = Object.keys(localStorage);
  out.beforeKeys = Object.keys(before);
  // show a sample value
  const k = Object.keys(localStorage)[0];
  if (k) out.sample = { key: k, value: localStorage.getItem(k)?.slice(0, 600) };
  return out;
}

() => {
  const out = {};
  // Look for any exposed global API / config
  out.windowKeys = Object.keys(window).filter(k => /mini|paint|app|config|file|layer/i.test(k)).slice(0,40);
  // Is there a FileSaver / saveAs?
  out.hasSaveAs = typeof window.saveAs;
  out.hasURL = typeof URL.createObjectURL;
  // Check the download helper names present in bundle via anchors
  out.aDownload = [...document.querySelectorAll('a[download]')].map(a=>a.download);
  return out;
}

() => {
  const out = {};
  const safe = (o) => { try { return Object.keys(o).slice(0,60); } catch { return 'n/a'; } };
  out.FileSave = safe(window.FileSave);
  out.FileOpen = safe(window.FileOpen);
  out.AppConfig = safe(window.AppConfig);
  out.Layers = safe(window.Layers);
  // save method signatures
  out.saveMeths = window.FileSave ? Object.getOwnPropertyNames(window.FileSave).concat(Object.getOwnPropertyNames(Object.getPrototypeOf(window.FileSave)||{})).slice(0,40) : null;
  return out;
}

