        {editor.selection && (
          <div
            className="mp-selection-box"
            aria-hidden="true"
            style={{
              position: "absolute",
              left: editor.selection.x * scale,
              top: editor.selection.y * scale,
              width: editor.selection.width * scale,
              height: editor.selection.height * scale,
              border: "1px dashed #000",
              pointerEvents: "none",
            }}
          />
        )}
        {editor.guides.map((g) => (
          <div
            key={g.id}
            className="mp-guide"
            aria-hidden="true"
            style={{
              position: "absolute",
              pointerEvents: "none",
              background: "#37c3ff",
              ...(g.type === "vertical"
