53	function rgbToHsv(r: number, g: number, b: number) {
54	  r /= 255;
55	  g /= 255;
56	  b /= 255;
57	  const max = Math.max(r, g, b),
58	    min = Math.min(r, g, b);
59	  const d = max - min;
60	  let h = 0;
61	  if (d !== 0) {
62	    if (max === r) h = ((g - b) / d) % 6;
63	    else if (max === g) h = (b - r) / d + 2;
64	    else h = (r - g) / d + 4;
65	    h *= 60;
66	    if (h < 0) h += 360;
67	  }
68	  const s = max === 0 ? 0 : d / max;
69	  return { h, s, v: max };
70	}
