() => {
  const before = { info: document.body.innerText.match(/\d+ x \d+ px/)?.[0] };
  const canvas = document.querySelector('.mp-canvas-stage canvas');
  before.backing = { w: canvas.width, h: canvas.height };
  before.css = Math.round(canvas.getBoundingClientRect().width);
  // click zoom-out twice via preview controls
  const minus = [...document.querySelectorAll('.mp-mini-btn')].find(b => b.textContent.trim()==='-');
  minus.click(); minus.click();
  const after = { info: document.body.innerText.match(/\d+ x \d+ px/)?.[0] };
  after.backing = { w: canvas.width, h: canvas.height };
  after.css = Math.round(canvas.getBoundingClientRect().width);
  return { before, after };
}

