48	  else if (h < 240) [r, g, b] = [0, x, c];
49	  else if (h < 300) [r, g, b] = [x, 0, c];
50	  else [r, g, b] = [c, 0, x];
51	  return { r: (r + m) * 255, g: (g + m) * 255, b: (b + m) * 255 };
