66	  r /= 255;
67	  g /= 255;
68	  b /= 255;
69	  const max = Math.max(r, g, b),
70	    min = Math.min(r, g, b);
71	  const d = max - min;
72	  let h = 0;
73	  if (d !== 0) {
74	    if (max === r) h = ((g - b) / d) % 6;
75	    else if (max === g) h = (b - r) / d + 2;
76	    else h = (r - g) / d + 4;
77	    h *= 60;
78	    if (h < 0) h += 360;
79	  }
80	  const s = max === 0 ? 0 : d / max;
81	  return { h, s, v: max };
