/* Standard document sizes, largest first. A new document starts at the biggest
   one that still fits the visible canvas area, otherwise a matching custom size
   (leaving a small margin for the surrounding chrome). */
const SIZE_PRESETS: [number, number][] = [
  [3840, 2160],
  [1920, 1080],
  [1600, 1200],
  [1280, 720],
  [1024, 768],
  [800, 600],
  [640, 480],
];

function pickInitialSize(): { w: number; h: number } {
  if (typeof window === "undefined") return { w: 1280, h: 720 };
  /* canvas area = viewport minus the 30px menu, 40px toolbar strip, 40px tool
     sidebar, 200px sidebar and 10px side margins */
  const availW = Math.max(1, window.innerWidth - 250);
  const availH = Math.max(1, window.innerHeight - 112);
  for (const [w, h] of SIZE_PRESETS) {
    if (w <= availW && h <= availH) return { w, h };
  }
  /* nothing fits: fall back to the widest aspect that fills the area */
  const w = Math.min(462, availW);
  const h = Math.max(1, Math.min(Math.round((w * 9) / 16 + 50), availH));
  return { w, h };
}

