  const errs = [];
  page.on('console', m => { if (m.type()==='error') errs.push(m.text()); });
  page.on('pageerror', e => errs.push('pageerror: '+e.message));
  await page.goto('http://localhost:4173');
  await page.waitForTimeout(500);
  const c = page.locator('.mp-canvas-stage canvas');
  const b = await c.boundingBox();
  // draw at 100%
  await page.mouse.move(b.x + 100, b.y + 100);
  await page.mouse.down();
  for (let i=0;i<10;i++) await page.mouse.move(b.x+100+i*15, b.y+100+Math.sin(i)*40);
  await page.mouse.up();
  await page.waitForTimeout(200);
  // zoom out 3 notches then draw again in a different spot
  for (let i=0;i<3;i++){ await page.locator('.mp-mini-btn').first().click(); await page.waitForTimeout(80); }
  await page.waitForTimeout(300);
  const b2 = await page.locator('.mp-canvas-stage canvas').boundingBox();
  await page.mouse.move(b2.x + 60, b2.y + 200);
  await page.mouse.down();
  for (let i=0;i<10;i++) await page.mouse.move(b2.x+60+i*12, b2.y+200-Math.sin(i)*35);
  await page.mouse.up();
  await page.waitForTimeout(300);
  await page.screenshot({ path: '.playwright-mcp/zoom-draw.png', scale: 'css' });
  return JSON.stringify({ errs });
}

