async (page) => {
  const errs = [];
  page.on('console', m => { if (m.type()==='error') errs.push(m.text()); });
  page.on('pageerror', e => errs.push('pageerror: '+e.message));
  const log = {};
  await page.goto('http://localhost:4173');
  await page.waitForTimeout(500);

  // 1. CHROME + rendered canvas
  log.chrome = await page.evaluate(() => {
    const menus = [...document.querySelectorAll('.mp-menu-title')].map(m=>m.textContent);
    const tools = document.querySelectorAll('.mp-tool').length;
    const blocks = [...document.querySelectorAll('.mp-block-heading')].map(h=>h.textContent.trim().replace(/[▲▼]/g,'').trim());
    const c = document.querySelector('.mp-canvas-stage canvas');
    return { menus, tools, blocks, canvas: {w:c.width,h:c.height} };
  });

  // 2. ZOOM changes display scale, not doc size
  const before = await page.evaluate(() => { const c=document.querySelector('.mp-canvas-stage canvas'); return {cw:c.width, doc:document.body.innerText.match(/(\d+) x (\d+) px/).slice(1,3).join('x')}; });
  await page.locator('.mp-mini-btn').first().click();
  await page.locator('.mp-mini-btn').first().click();
  await page.waitForTimeout(300);
  const after = await page.evaluate(() => { const c=document.querySelector('.mp-canvas-stage canvas'); return {cw:c.width, doc:document.body.innerText.match(/(\d+) x (\d+) px/).slice(1,3).join('x')}; });
  log.zoom = { before, after };

  // 3. SAVE project -> nonempty structured document
  await page.evaluate(() => { window.__cap=null; HTMLAnchorElement.prototype.click = function(){ window.__cap={download:this.download, href:String(this.href)}; }; });
  await page.locator('.mp-menu-title:has-text("File")').click();
  await page.locator('.mp-menu-item:has-text("Save As")').first().click();
  await page.waitForTimeout(150);
  await page.locator('.mp-dialog-btn:has-text("Ok")').click();
  await page.waitForTimeout(300);
  log.save = await page.evaluate(() => {
    const json = decodeURIComponent((window.__cap?.href||'').split(',').slice(1).join(','));
    const p = JSON.parse(json);
    return { download: window.__cap?.download, chars: json.length, hasInfo: !!p.info, layers: p.layers.length, keys: Object.keys(p) };
  });

  // 4. NEW document still works
  await page.locator('.mp-menu-title:has-text("File")').click();
  await page.locator('.mp-menu-item:has-text("New")').first().click();
  await page.waitForTimeout(200);
  const dlg = await page.locator('.mp-dialog').count();
  await page.locator('.mp-dialog-btn:has-text("Cancel")').click();
  log.newDialog = dlg;

  // 5. QUICK SAVE
  await page.locator('.mp-menu-title:has-text("File")').click();
  await page.locator('.mp-menu-item:has-text("Quick Save")').first().click();
  await page.waitForTimeout(200);
  log.quickSave = await page.evaluate(() => { const r = localStorage.getItem('quicksave_data'); return r ? {len:r.length, valid: !!JSON.parse(r).info} : null; });

  return JSON.stringify({ errs, log }, null, 1);
}

