async (page) => {
  await page.goto('http://localhost:4173');
  await page.waitForTimeout(500);
  const c = page.locator('.mp-canvas-stage canvas');
  const b = await c.boundingBox();
  const pixelCount = async () => page.evaluate(() => {
    const cv = document.querySelector('.mp-canvas-stage canvas');
    const ctx = cv.getContext('2d');
    const d = ctx.getImageData(0,0,cv.width,cv.height).data;
    let nonWhite=0; for (let i=0;i<d.length;i+=4){ if (d[i]<240||d[i+1]<240||d[i+2]<240) nonWhite++; }
    return nonWhite;
  });
  const p0 = await pixelCount();
  await page.mouse.move(b.x+100, b.y+100); await page.mouse.down();
  for (let i=0;i<12;i++) await page.mouse.move(b.x+100+i*12, b.y+100+Math.sin(i)*30);
  await page.mouse.up(); await page.waitForTimeout(200);
  const p1 = await pixelCount();
  await page.keyboard.press('Control+z'); await page.waitForTimeout(200);
  const p2 = await pixelCount();
  await page.keyboard.press('Control+y'); await page.waitForTimeout(200);
  const p3 = await pixelCount();
  return JSON.stringify({ p0, p1, p2, p3, drawWorks: p1>p0, undoWorks: p2<p1, redoWorks: p3>p2 });
}

